slots.VIEW:
SIM = {
  duration: 3.62217,
  bodies: [
    { id: "block_A", at: function (s) { const b = s.block_A; return [b.x, b.y]; } },
    { id: "block_B", at: function (s) { const b = s.block_B; return [b.x, b.y]; } },
    { id: "block_C", at: function (s) { const b = s.block_C; return [b.x, b.y]; } }
  ],
  phases: [{ t0: 0, t1: 0.49027 }, { t0: 0.49027, t1: 1.18526 }, { t0: 1.18526, t1: 2.05137 }, { t0: 2.05137, t1: 3.62217 }],
};

slots.drawFrame:
// 传送带（带面顶 y = -0.25，顺时针转：刻度相位随时间右移）
Draw.belt([-3, -0.25], [7.2, -0.25], { r: 0.25, ticks: 26, tickPhase: t * 1.2 });

// 定滑轮与上方吊架
Draw.line([7.0, 1.15], [9.0, 1.15], { width: 2 });
Draw.line([8.0, 1.15], [8.0, 0.45], { width: 2 });
Draw.pulley([8.0, 0.05], 0.4);

// 轻绳：A 右端 → 滑轮左切点（水平，与带面平行）
Draw.line([state.block_A.x + 0.45, 0.05], [7.6, 0.05]);

// 轻绳：滑轮 → B 顶端（竖直）
Draw.line([8.0, -0.35], [8.0, state.block_B.y + 0.3]);

// 轻绳：B 底端 → C 顶端（B、C 间绳剪断后不再画）
if (t < 2.05137) {
  Draw.line([8.0, state.block_B.y - 0.3], [8.0, state.block_C.y + 0.3]);
}

// 挡板 P（t = 0 撤去，仅起始帧可见）
if (t < 0.02) {
  Draw.line([-0.62, -0.25], [-0.62, 0.8], { width: 3 });
}

// 作用在 A 上的水平外力 F = -20x
const Fx = -20 * state.block_A.x;
if (Math.abs(Fx) > 2) {
  Draw.arrow([state.block_A.x, state.block_A.y + 0.5], [Fx > 0 ? 1 : -1, 0], { category: 'force', mag: Math.abs(Fx) });
}

// 三个物块（质心位置取自 state）
Draw.box([state.block_A.x, state.block_A.y], 0.9, 0.6);
Draw.box([state.block_B.x, state.block_B.y], 0.7, 0.6);
Draw.box([state.block_C.x, state.block_C.y], 0.7, 0.6);

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(3.62217, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "block_A.x", label: "block_A 水平位置", value: state.block_A.x, unit: 'm' });
out.push({ key: "block_A.y", label: "block_A 竖直位置", value: state.block_A.y, unit: 'm' });
out.push({ key: "block_A.vx", label: "block_A 水平速度", value: (b.block_A.x - a.block_A.x) / dt, unit: 'm/s' });
out.push({ key: "block_A.vy", label: "block_A 竖直速度", value: (b.block_A.y - a.block_A.y) / dt, unit: 'm/s' });
out.push({ key: "block_B.x", label: "block_B 水平位置", value: state.block_B.x, unit: 'm' });
out.push({ key: "block_B.y", label: "block_B 竖直位置", value: state.block_B.y, unit: 'm' });
out.push({ key: "block_B.vx", label: "block_B 水平速度", value: (b.block_B.x - a.block_B.x) / dt, unit: 'm/s' });
out.push({ key: "block_B.vy", label: "block_B 竖直速度", value: (b.block_B.y - a.block_B.y) / dt, unit: 'm/s' });
out.push({ key: "block_C.x", label: "block_C 水平位置", value: state.block_C.x, unit: 'm' });
out.push({ key: "block_C.y", label: "block_C 竖直位置", value: state.block_C.y, unit: 'm' });
out.push({ key: "block_C.vx", label: "block_C 水平速度", value: (b.block_C.x - a.block_C.x) / dt, unit: 'm/s' });
out.push({ key: "block_C.vy", label: "block_C 竖直速度", value: (b.block_C.y - a.block_C.y) / dt, unit: 'm/s' });
return out;
